using System.Text.Json;
using LoanSystem.Modules.LoanOrigination.Application;
using LoanSystem.Modules.LoanOrigination.Domain;
using Microsoft.EntityFrameworkCore;
namespace LoanSystem.Modules.LoanOrigination.Infrastructure;

public sealed class LoanOriginationDbContext(DbContextOptions<LoanOriginationDbContext> options) : DbContext(options), ILoanApplicationStore, IPropertyInspectionStore
{
    public DbSet<LoanApplication> LoanApplications => Set<LoanApplication>();
    public DbSet<PropertyInspection> PropertyInspections => Set<PropertyInspection>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var b = modelBuilder.Entity<LoanApplication>(); b.ToTable("loan_applications", "loan_origination"); b.HasKey(x => x.Id); b.Ignore(x => x.DomainEvents); b.Property(x => x.Id).HasColumnName("loan_application_id"); b.Property(x => x.BorrowerId).HasColumnName("borrower_id"); b.Property(x => x.LoanProductId).HasColumnName("loan_product_id"); b.Property(x => x.LoanProductVersionId).HasColumnName("loan_product_version_id"); b.Property(x => x.RequestedAmount).HasColumnName("requested_amount").HasPrecision(19, 4); b.Property(x => x.Currency).HasColumnName("currency").HasColumnType("char(3)"); b.Property(x => x.FinancingType).HasColumnName("financing_type").HasMaxLength(100); b.Property(x => x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(30); b.Property(x => x.BorrowerSnapshot).HasColumnName("borrower_snapshot").HasColumnType("nvarchar(max)").HasConversion(x => JsonSerializer.Serialize(x, JsonSerializerOptions.Default), x => JsonSerializer.Deserialize<BorrowerSnapshot>(x, JsonSerializerOptions.Default)!); b.Property(x => x.ProductSnapshot).HasColumnName("product_snapshot").HasColumnType("nvarchar(max)").HasConversion(x => JsonSerializer.Serialize(x, JsonSerializerOptions.Default), x => JsonSerializer.Deserialize<ProductSnapshot>(x, JsonSerializerOptions.Default)!); b.Property(x => x.EligibilityDecision).HasColumnName("eligibility_snapshot").HasColumnType("nvarchar(max)").HasConversion(x => x == null ? null : JsonSerializer.Serialize(x, JsonSerializerOptions.Default), x => x == null ? null : JsonSerializer.Deserialize<EligibilityDecision>(x, JsonSerializerOptions.Default)); b.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc"); b.Property(x => x.UpdatedAtUtc).HasColumnName("updated_at_utc"); b.Property(x => x.SubmittedAtUtc).HasColumnName("submitted_at_utc"); b.Property(x => x.UnitApproval).HasColumnName("unit_approval").HasColumnType("nvarchar(max)").HasConversion(x => x == null ? null : JsonSerializer.Serialize(x, JsonSerializerOptions.Default), x => x == null ? null : JsonSerializer.Deserialize<UnitApprovalDecision>(x, JsonSerializerOptions.Default)); b.Property(x => x.InspectionPrerequisiteStatus).HasColumnName("inspection_prerequisite_status").HasConversion<string>().HasMaxLength(30); b.Property(x => x.MortgageStatus).HasColumnName("mortgage_status").HasConversion<string>().HasMaxLength(30); b.Property(x => x.MortgageDecision).HasColumnName("mortgage_decision").HasColumnType("nvarchar(max)").HasConversion(x => x == null ? null : JsonSerializer.Serialize(x, JsonSerializerOptions.Default), x => x == null ? null : JsonSerializer.Deserialize<MortgageDecision>(x, JsonSerializerOptions.Default)); b.Property(x => x.DocumentPrerequisiteStatus).HasColumnName("document_prerequisite_status").HasConversion<string>().HasMaxLength(30); b.Property(x => x.CommitteeApproval).HasColumnName("committee_approval").HasColumnType("nvarchar(max)").HasConversion(x => x == null ? null : JsonSerializer.Serialize(x, JsonSerializerOptions.Default), x => x == null ? null : JsonSerializer.Deserialize<CommitteeApprovalDecision>(x, JsonSerializerOptions.Default)); b.Property(x => x.RejectedAtUtc).HasColumnName("rejected_at_utc"); b.Property(x => x.RowVersion).HasColumnName("row_version").IsRowVersion(); b.HasIndex(x => x.BorrowerId).HasDatabaseName("IX_loan_applications_borrower_id"); b.HasIndex(x => x.LoanProductId).HasDatabaseName("IX_loan_applications_product_id"); b.HasIndex(x => x.Status).HasDatabaseName("IX_loan_applications_status"); b.HasIndex(x => x.CreatedAtUtc).HasDatabaseName("IX_loan_applications_created_at");
        var d = modelBuilder.Entity<LoanApplicationDocumentReference>(); d.ToTable("application_documents", "loan_origination"); d.HasKey(x => new { x.LoanApplicationId, x.DocumentId }); d.Property(x => x.LoanApplicationId).HasColumnName("loan_application_id"); d.Property(x => x.DocumentId).HasColumnName("document_id"); d.Property(x => x.DocumentType).HasColumnName("document_type").HasConversion<string>().HasMaxLength(30); d.Property(x => x.IsRequired).HasColumnName("is_required"); d.Property(x => x.AttachedAtUtc).HasColumnName("attached_at_utc"); b.HasMany(x => x.ApplicationDocuments).WithOne().HasForeignKey(x => x.LoanApplicationId).OnDelete(DeleteBehavior.Restrict); b.Navigation(x => x.ApplicationDocuments).HasField("_applicationDocuments").UsePropertyAccessMode(PropertyAccessMode.Field);
        var i = modelBuilder.Entity<PropertyInspection>(); i.ToTable("property_inspections", "loan_origination"); i.HasKey(x => x.Id); i.Ignore(x => x.DomainEvents); i.Property(x => x.Id).HasColumnName("property_inspection_id"); i.Property(x => x.LoanApplicationId).HasColumnName("loan_application_id"); i.Property(x => x.InspectorId).HasColumnName("inspector_id"); i.Property(x => x.Governorate).HasColumnName("governorate").HasMaxLength(100); i.Property(x => x.State).HasColumnName("state").HasMaxLength(100); i.Property(x => x.Area).HasColumnName("area").HasMaxLength(200); i.Property(x => x.NumberOfFloors).HasColumnName("number_of_floors"); i.Property(x => x.NumberOfRooms).HasColumnName("number_of_rooms"); i.Property(x => x.PropertyArea).HasColumnName("property_area").HasPrecision(18, 2); i.Property(x => x.PropertyCondition).HasColumnName("property_condition").HasMaxLength(500); i.Property(x => x.InspectionDate).HasColumnName("inspection_date"); i.Property(x => x.Result).HasColumnName("result").HasMaxLength(500); i.Property(x => x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(30); i.Property(x => x.Notes).HasColumnName("notes").HasColumnType("nvarchar(max)"); i.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc"); i.Property(x => x.UpdatedAtUtc).HasColumnName("updated_at_utc"); i.Property(x => x.FinalizedAtUtc).HasColumnName("finalized_at_utc"); i.Property(x => x.RowVersion).HasColumnName("row_version").IsRowVersion(); i.HasOne<LoanApplication>().WithMany().HasForeignKey(x => x.LoanApplicationId).OnDelete(DeleteBehavior.Restrict);
    }

    public Task AddAsync(PropertyInspection value, CancellationToken ct) => PropertyInspections.AddAsync(value, ct).AsTask();
    public Task<PropertyInspection?> FindInspectionAsync(Guid id, CancellationToken ct) => PropertyInspections.SingleOrDefaultAsync(x => x.Id == id, ct);
    Task<PropertyInspection?> IPropertyInspectionStore.FindAsync(Guid id, CancellationToken ct) => FindInspectionAsync(id, ct);
    public async Task<IReadOnlyList<PropertyInspection>> FindByApplicationAsync(Guid applicationId, CancellationToken ct) => await PropertyInspections.Where(x => x.LoanApplicationId == applicationId).OrderBy(x => x.CreatedAtUtc).ToListAsync(ct);
    public void Expect(PropertyInspection value, byte[] expected) { if (!value.RowVersion.AsSpan().SequenceEqual(expected)) throw new InspectionConcurrencyException(); Entry(value).Property(x => x.RowVersion).OriginalValue = expected; }
    public Task AddAsync(LoanApplication value, CancellationToken ct) => LoanApplications.AddAsync(value, ct).AsTask();
    public Task<LoanApplication?> FindAsync(Guid id, CancellationToken ct) => LoanApplications.Include(x => x.ApplicationDocuments).SingleOrDefaultAsync(x => x.Id == id, ct);
    public Task<int> CountConflictingApplicationsAsync(Guid borrowerId, Guid excludeApplicationId, CancellationToken ct) => LoanApplications.AsNoTracking().CountAsync(x => x.BorrowerId == borrowerId && x.Id != excludeApplicationId && (x.Status == LoanApplicationStatus.Draft || x.Status == LoanApplicationStatus.Submitted || x.Status == LoanApplicationStatus.UnitApproved || x.Status == LoanApplicationStatus.CommitteeApproved || x.Status == LoanApplicationStatus.PrerequisitesPending || x.Status == LoanApplicationStatus.ReadyForFinalApproval), ct);
    public void Expect(LoanApplication value, byte[] expected)
    {
        if (!value.RowVersion.AsSpan().SequenceEqual(expected))
            throw new LoanApplicationConcurrencyException();
        Entry(value).Property(x => x.RowVersion).OriginalValue = expected;
    }
    public async Task SaveAsync(CancellationToken ct) { try { await SaveChangesAsync(ct); } catch (DbUpdateConcurrencyException) { throw new LoanApplicationConcurrencyException(); } }
    async Task IPropertyInspectionStore.SaveAsync(CancellationToken ct) { try { await SaveChangesAsync(ct); } catch (DbUpdateConcurrencyException) { throw new InspectionConcurrencyException(); } }
    public async Task<LoanApplicationPage> SearchAsync(LoanApplicationSearch search, CancellationToken ct) { var q = LoanApplications.AsNoTracking(); if (search.LoanApplicationId.HasValue) q = q.Where(x => x.Id == search.LoanApplicationId); if (search.BorrowerId.HasValue) q = q.Where(x => x.BorrowerId == search.BorrowerId); if (search.LoanProductId.HasValue) q = q.Where(x => x.LoanProductId == search.LoanProductId); if (search.Status.HasValue) q = q.Where(x => x.Status == search.Status); var count = await q.CountAsync(ct); var values = await q.OrderByDescending(x => x.CreatedAtUtc).ThenBy(x => x.Id).Skip((search.PageNumber - 1) * search.PageSize).Take(search.PageSize).ToListAsync(ct); var rows = values.Select(x => new LoanApplicationListItem(x.Id, x.BorrowerId, x.BorrowerSnapshot.FullName, x.LoanProductId, x.ProductSnapshot.ProductName, x.RequestedAmount, x.Currency, x.FinancingType, x.Status.ToString(), x.CreatedAtUtc, x.UpdatedAtUtc, x.SubmittedAtUtc)).ToArray(); return new(rows, search.PageNumber, search.PageSize, count); }
}
